164	    /// @inheritdoc ILegionAbstractSale
165	    function refund() external virtual whenNotPaused whenRefundPeriodNotOver whenSaleNotCanceled {
166	        // Get the investor position ID
167	        uint256 positionId = _getInvestorPositionId(msg.sender);
168	
169	        // Verify that the position exists
170	        _verifyPositionExists(positionId);
171	
172	        // Verify that the investor has not refunded
173	        _verifyHasNotRefunded(positionId);
174	
175	        // Cache the amount to refund in memory
176	        uint256 amountToRefund = s_investorPositions[positionId].investedCapital;
177	
178	        // Set the total invested capital for the investor to 0
179	        s_investorPositions[positionId].investedCapital = 0;
180	
181	        // Flag that the investor has refunded
182	        s_investorPositions[positionId].hasRefunded = true;
183	
184	        // Decrement total capital invested from investors
185	        s_saleStatus.totalCapitalInvested -= amountToRefund;
186	
187	        // Emit CapitalRefunded
188	        emit CapitalRefunded(amountToRefund, msg.sender, positionId);
189	
190	        // Transfer the refunded amount back to the investor
191	        SafeTransferLib.safeTransfer(s_addressConfig.bidToken, msg.sender, amountToRefund);
192	    }
193	
194	    /// @inheritdoc ILegionAbstractSale
195	    function withdrawRaisedCapital()
196	        external
197	        virtual
198	        onlyProject
199	        whenNotPaused
200	        whenRefundPeriodIsOver
201	        whenSaleNotCanceled
202	        whenSaleResultsArePublished
203	        whenTokensSupplied
204	    {
205	        // Verify that the project can withdraw capital
206	        _verifyCanWithdrawCapital();
207	
208	        // Flag that the capital has been withdrawn
209	        s_saleStatus.capitalWithdrawn = true;
210	
211	        // Cache value in memory
212	        uint256 _totalCapitalRaised = s_saleStatus.totalCapitalRaised;
213	
214	        // Set the total capital that has been withdrawn
215	        s_saleStatus.totalCapitalWithdrawn = _totalCapitalRaised;
216	
217	        // Cache Legion Sale Address Configuration
218	        LegionSaleAddressConfiguration memory addressConfig = s_addressConfig;
219	
220	        // Cache Legion Sale Configuration
221	        LegionSaleConfiguration memory saleConfig = s_saleConfig;
222	
223	        // Calculate Legion Fee
224	        uint256 _legionFee =
225	            (saleConfig.legionFeeOnCapitalRaisedBps * _totalCapitalRaised) / Constants.BASIS_POINTS_DENOMINATOR;
226	
227	        // Calculate Referrer Fee
228	        uint256 _referrerFee =
229	            (saleConfig.referrerFeeOnCapitalRaisedBps * _totalCapitalRaised) / Constants.BASIS_POINTS_DENOMINATOR;
230	
231	        // Emit CapitalWithdrawn
232	        emit CapitalWithdrawn(_totalCapitalRaised);
233	
234	        // Transfer the raised capital to the project owner
235	        SafeTransferLib.safeTransfer(
236	            addressConfig.bidToken, msg.sender, (_totalCapitalRaised - _legionFee - _referrerFee)
237	        );
238	
239	        // Transfer the Legion fee to the Legion fee receiver address
240	        if (_legionFee != 0) {
241	            SafeTransferLib.safeTransfer(addressConfig.bidToken, addressConfig.legionFeeReceiver, _legionFee);
242	        }
243	
244	        // Transfer the Referrer fee to the Referrer fee receiver address
245	        if (_referrerFee != 0) {
246	            SafeTransferLib.safeTransfer(addressConfig.bidToken, addressConfig.referrerFeeReceiver, _referrerFee);
247	        }
248	    }
249	
250	    /// @inheritdoc ILegionAbstractSale
251	    function claimTokenAllocation(
252	        uint256 amount,
253	        LegionVestingManager.LegionInvestorVestingConfig calldata investorVestingConfig,
254	        bytes32[] calldata proof
255	    )
256	        external
257	        virtual
258	        whenNotPaused
259	        whenSaleNotCanceled
260	        whenRefundPeriodIsOver
261	        whenSaleResultsArePublished
262	    {
263	        // Get the investor position ID
264	        uint256 positionId = _getInvestorPositionId(msg.sender);
265	
266	        // Verify that the position exists
267	        _verifyPositionExists(positionId);
268	
269	        // Verify that the investor has not refunded
270	        _verifyHasNotRefunded(positionId);
271	
272	        // Verify that the vesting configuration is valid
273	        _verifyValidVestingConfig(investorVestingConfig);
274	
275	        // Verify that the investor is eligible to claim the requested amount
276	        _verifyCanClaimTokenAllocation(msg.sender, amount, investorVestingConfig, proof);
277	
278	        // Load the investor position
279	        InvestorPosition storage position = s_investorPositions[positionId];
280	
281	        // Cache Legion Sale Address Configuration
282	        LegionSaleAddressConfiguration memory addressConfig = s_addressConfig;
283	
284	        // Mark that the token amount has been settled
285	        position.hasSettled = true;
286	
287	        // Calculate the amount to be distributed on claim
288	        uint256 amountToDistributeOnClaim =
289	            amount * investorVestingConfig.tokenAllocationOnTGERate / Constants.TOKEN_ALLOCATION_RATE_DENOMINATOR;
290	
291	        // Calculate the remaining amount to be vested
292	        uint256 amountToBeVested = amount - amountToDistributeOnClaim;
293	
294	        // Emit TokenAllocationClaimed
295	        emit TokenAllocationClaimed(amountToBeVested, amountToDistributeOnClaim, msg.sender, positionId);
296	
297	        // Deploy vesting and distribute tokens only if there is anything to distribute
298	        if (amountToBeVested != 0) {
299	            // Deploy a vesting contract for the investor
300	            address payable vestingAddress = _createVesting(investorVestingConfig, addressConfig.askToken);
301	
302	            // Save the vesting address for the investor
303	            position.vestingAddress = vestingAddress;
304	
305	            // Transfer the allocated amount of tokens for distribution to the vesting contract
306	            SafeTransferLib.safeTransfer(addressConfig.askToken, vestingAddress, amountToBeVested);
307	        }
308	
309	        if (amountToDistributeOnClaim != 0) {
310	            // Transfer the allocated amount of tokens for distribution on claim
311	            SafeTransferLib.safeTransfer(addressConfig.askToken, msg.sender, amountToDistributeOnClaim);
312	        }
313	    }
314	
315	    /// @inheritdoc ILegionAbstractSale
316	    function withdrawExcessInvestedCapital(
317	        uint256 amount,
318	        bytes32[] calldata proof
319	    )
320	        external
321	        virtual
322	        whenNotPaused
323	        whenSaleNotCanceled
324	    {
325	        // Get the investor position ID
326	        uint256 positionId = _getInvestorPositionId(msg.sender);
327	
328	        // Verify that the position exists
329	        _verifyPositionExists(positionId);
330	
331	        // Verify that the investor has not refunded
332	        _verifyHasNotRefunded(positionId);
333	
334	        // Verify that the investor is eligible to get excess capital back
335	        _verifyCanClaimExcessCapital(msg.sender, positionId, amount, proof);
336	
337	        // Mark that the excess capital has been returned
338	        s_investorPositions[positionId].hasClaimedExcess = true;
339	
340	        // Decrement the total invested capital for the investor
341	        s_investorPositions[positionId].investedCapital -= amount;
342	
343	        // Decrement total capital invested from all investors
344	        s_saleStatus.totalCapitalInvested -= amount;
345	
346	        // Emit ExcessCapitalWithdrawn
347	        emit ExcessCapitalWithdrawn(amount, msg.sender, positionId);
348	
349	        // Transfer the excess capital back to the investor
350	        if (amount > 0) SafeTransferLib.safeTransfer(s_addressConfig.bidToken, msg.sender, amount);
351	    }
352	
353	    /// @inheritdoc ILegionAbstractSale
354	    function releaseVestedTokens() external virtual whenNotPaused {
355	        // Get the investor position ID
356	        uint256 positionId = _getInvestorPositionId(msg.sender);
357	
358	        // Verify that the position exists
359	        _verifyPositionExists(positionId);
360	
361	        // Get the investor vesting address
362	        address investorVestingAddress = s_investorPositions[positionId].vestingAddress;
363	
364	        // Revert in case there's no vesting for the investor
365	        if (investorVestingAddress == address(0)) revert Errors.LegionSale__ZeroAddressProvided();
366	
367	        // Release tokens to the investor account
368	        ILegionVesting(investorVestingAddress).release(s_addressConfig.askToken);
369	    }
370	
371	    /// @inheritdoc ILegionAbstractSale
372	    function supplyTokens(
373	        uint256 amount,
374	        uint256 legionFee,
375	        uint256 referrerFee
376	    )
377	        external
378	        virtual
379	        onlyProject
380	        whenNotPaused
381	        whenSaleNotCanceled
382	        whenTokensNotSupplied
383	    {
384	        // Verify that tokens can be supplied for distribution
385	        _verifyCanSupplyTokens(amount);
386	
387	        // Flag that tokens have been supplied
388	        s_saleStatus.tokensSupplied = true;
389	
390	        // Cache Legion Sale Configuration
391	        LegionSaleConfiguration memory saleConfig = s_saleConfig;
392	
393	        // Calculate the expected Legion Fee amount
394	        uint256 expectedLegionFeeAmount =
395	            (saleConfig.legionFeeOnTokensSoldBps * amount) / Constants.BASIS_POINTS_DENOMINATOR;
396	
397	        // Calculate the expected Referrer Fee amount
398	        uint256 expectedReferrerFeeAmount =
399	            (saleConfig.referrerFeeOnTokensSoldBps * amount) / Constants.BASIS_POINTS_DENOMINATOR;
400	

